DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch11$PT117-S3-Q7$batch11$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT117-S3-Q7'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch11$PT117-S3-Q7$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch11$Statements$batch11$, $batch11$No keyboarding skills → can't use a computer. Can't use a computer → can't write essays in a word processor.$batch11$), (1, $batch11$Evaluate$batch11$, $batch11$Chain them: no keyboarding → no computer → no word processing. The contrapositive runs backward: word processing → computer → some keyboarding skills.$batch11$), (2, $batch11$Goal$batch11$, $batch11$If you can write essays in a word processor, you have some keyboarding skills.$batch11$)) v(position,label,body) WHERE q.qid=$batch11$PT117-S3-Q7$batch11$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
